python3 << 'PYEOF'
import csv, json, statistics
from collections import defaultdict

with open('benchmark/data.csv') as f:
    reader = csv.DictReader(f)
    rows = list(reader)

for r in rows:
    r['year'] = int(r['year'])
    r['salary'] = float(r['salary'])
    r['ai_risk_score'] = float(r['ai_risk_score'])
    r['skill_demand_score'] = int(r['skill_demand_score'])
    r['job_openings'] = int(r['job_openings'])
    r['job_survival_class'] = int(r['job_survival_class'])

results = {}

# === KPI 1: Average AI Risk Score by year ===
risk_by_year = defaultdict(list)
for r in rows:
    risk_by_year[r['year']].append(r['ai_risk_score'])
results['risk_by_year'] = {y: round(statistics.mean(v), 4) for y, v in sorted(risk_by_year.items())}

# AI risk by job title
risk_by_job = defaultdict(list)
for r in rows:
    risk_by_job[r['job_title']].append(r['ai_risk_score'])
results['risk_by_job'] = {k: round(statistics.mean(v), 4) for k, v in sorted(risk_by_job.items(), key=lambda x: -statistics.mean(x[1]))}

# AI risk by country
risk_by_country = defaultdict(list)
for r in rows:
    risk_by_country[r['country']].append(r['ai_risk_score'])
results['risk_by_country'] = {k: round(statistics.mean(v), 4) for k, v in sorted(risk_by_country.items(), key=lambda x: -statistics.mean(x[1]))}

# AI risk by experience level
risk_by_exp = defaultdict(list)
for r in rows:
    risk_by_exp[r['experience_level']].append(r['ai_risk_score'])
results['risk_by_exp'] = {k: round(statistics.mean(v), 4) for k, v in sorted(risk_by_exp.items(), key=lambda x: -statistics.mean(x[1]))}

# AI risk category distribution
risk_cat_dist = defaultdict(int)
for r in rows:
    risk_cat_dist[r['ai_risk_category']] += 1
results['risk_cat_dist'] = dict(risk_cat_dist)

# Risk trend by job title and year
risk_job_year = defaultdict(lambda: defaultdict(list))
for r in rows:
    risk_job_year[r['job_title']][r['year']].append(r['ai_risk_score'])
results['risk_job_year'] = {job: {y: round(statistics.mean(v), 4) for y, v in sorted(years.items())} for job, years in risk_job_year.items()}

# === KPI 2: Median Salary ===
salary_by_year = defaultdict(list)
for r in rows:
    salary_by_year[r['year']].append(r['salary'])
results['salary_by_year'] = {y: round(statistics.median(v), 2) for y, v in sorted(salary_by_year.items())}

salary_by_country = defaultdict(list)
for r in rows:
    salary_by_country[r['country']].append(r['salary'])
results['salary_by_country'] = {k: round(statistics.median(v), 2) for k, v in sorted(salary_by_country.items(), key=lambda x: -statistics.median(x[1]))}

salary_by_job = defaultdict(list)
for r in rows:
    salary_by_job[r['job_title']].append(r['salary'])
results['salary_by_job'] = {k: round(statistics.median(v), 2) for k, v in sorted(salary_by_job.items(), key=lambda x: -statistics.median(x[1]))}

salary_by_exp = defaultdict(list)
for r in rows:
    salary_by_exp[r['experience_level']].append(r['salary'])
results['salary_by_exp'] = {k: round(statistics.median(v), 2) for k, v in sorted(salary_by_exp.items(), key=lambda x: -statistics.median(x[1]))}

salary_by_edu = defaultdict(list)
for r in rows:
    salary_by_edu[r['education_level']].append(r['salary'])
results['salary_by_edu'] = {k: round(statistics.median(v), 2) for k, v in sorted(salary_by_edu.items(), key=lambda x: -statistics.median(x[1]))}

# Salary by risk category
salary_by_risk = defaultdict(list)
for r in rows:
    salary_by_risk[r['ai_risk_category']].append(r['salary'])
results['salary_by_risk'] = {k: round(statistics.median(v), 2) for k, v in salary_by_risk.items()}

# Salary by year and country
sal_year_country = defaultdict(lambda: defaultdict(list))
for r in rows:
    sal_year_country[r['country']][r['year']].append(r['salary'])
results['sal_year_country'] = {c: {y: round(statistics.median(v), 2) for y, v in sorted(years.items())} for c, years in sal_year_country.items()}

# Salary by year and job
sal_year_job = defaultdict(lambda: defaultdict(list))
for r in rows:
    sal_year_job[r['job_title']][r['year']].append(r['salary'])
results['sal_year_job'] = {j: {y: round(statistics.median(v), 2) for y, v in sorted(years.items())} for j, years in sal_year_job.items()}

# === KPI 3: Job Survival Rate ===
survival_by_year = defaultdict(lambda: defaultdict(int))
for r in rows:
    survival_by_year[r['year']][r['job_survival_class']] += 1
results['survival_by_year'] = {}
for y in sorted(survival_by_year):
    total = sum(survival_by_year[y].values())
    at_risk = survival_by_year[y].get(0, 0)
    results['survival_by_year'][y] = {
        'total': total,
        'at_risk': at_risk,
        'moderate': survival_by_year[y].get(1, 0),
        'strong': survival_by_year[y].get(2, 0),
        'survival_rate': round((total - at_risk) / total * 100, 2)
    }

survival_by_job = defaultdict(lambda: defaultdict(int))
for r in rows:
    survival_by_job[r['job_title']][r['job_survival_class']] += 1
results['survival_by_job'] = {}
for j in survival_by_job:
    total = sum(survival_by_job[j].values())
    results['survival_by_job'][j] = {
        'class_0_pct': round(survival_by_job[j].get(0, 0) / total * 100, 2),
        'class_1_pct': round(survival_by_job[j].get(1, 0) / total * 100, 2),
        'class_2_pct': round(survival_by_job[j].get(2, 0) / total * 100, 2),
    }

# === KPI 4: Average Skill Demand Score ===
skill_demand_by_skill = defaultdict(list)
for r in rows:
    skill_demand_by_skill[r['primary_skill']].append(r['skill_demand_score'])
results['skill_demand_avg'] = {k: round(statistics.mean(v), 2) for k, v in sorted(skill_demand_by_skill.items(), key=lambda x: -statistics.mean(x[1]))}

skill_demand_by_year = defaultdict(lambda: defaultdict(list))
for r in rows:
    skill_demand_by_year[r['primary_skill']][r['year']].append(r['skill_demand_score'])
results['skill_demand_year'] = {s: {y: round(statistics.mean(v), 2) for y, v in sorted(years.items())} for s, years in skill_demand_by_year.items()}

# Skill demand vs survival
skill_survival = defaultdict(lambda: defaultdict(int))
for r in rows:
    skill_survival[r['primary_skill']][r['job_survival_class']] += 1
results['skill_survival'] = {}
for s in skill_survival:
    total = sum(skill_survival[s].values())
    results['skill_survival'][s] = {
        'class_2_pct': round(skill_survival[s].get(2, 0) / total * 100, 2),
        'class_0_pct': round(skill_survival[s].get(0, 0) / total * 100, 2)
    }

# === KPI 5: Total Job Openings Trend ===
openings_by_year = defaultdict(int)
for r in rows:
    openings_by_year[r['year']] += r['job_openings']
results['openings_by_year'] = {y: v for y, v in sorted(openings_by_year.items())}

openings_by_job_year = defaultdict(lambda: defaultdict(int))
for r in rows:
    openings_by_job_year[r['job_title']][r['year']] += r['job_openings']
results['openings_by_job_year'] = {j: {y: v for y, v in sorted(years.items())} for j, years in openings_by_job_year.items()}

# === Additional: Risk by education ===
risk_by_edu = defaultdict(list)
for r in rows:
    risk_by_edu[r['education_level']].append(r['ai_risk_score'])
results['risk_by_edu'] = {k: round(statistics.mean(v), 4) for k, v in sorted(risk_by_edu.items(), key=lambda x: -statistics.mean(x[1]))}

# Overall stats
results['overall'] = {
    'total_rows': len(rows),
    'avg_risk': round(statistics.mean(r['ai_risk_score'] for r in rows), 4),
    'median_salary': round(statistics.median(r['salary'] for r in rows), 2),
    'avg_skill_demand': round(statistics.mean(r['skill_demand_score'] for r in rows), 2),
    'total_openings': sum(r['job_openings'] for r in rows),
    'survival_rate': round(sum(1 for r in rows if r['job_survival_class'] >= 1) / len(rows) * 100, 2)
}

# Salary x risk correlation
import math
salaries = [r['salary'] for r in rows]
risks = [r['ai_risk_score'] for r in rows]
